
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_hapbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_hapbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.525713198680728e+00, -3.459581547499572e+00, -3.366979537863188e+00, -3.238838399347331e+00, -3.064516427751763e+00, -2.833111778084309e+00, -2.536525364965770e+00, -2.174845417712896e+00, -1.762799117851631e+00, -1.329166444412065e+00, -8.964985234296469e-01, -6.072348865624297e-01, -5.284301623264698e-01, -4.342692633948944e-01, -3.141447580406209e-01, -2.012951776752012e-01, -1.084608119706240e-01, -3.972692983790757e-02, -8.650730510121683e-03, -9.729634507057879e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


